// ====================================================================
// PARSE CONFIG PRG
// Kredensial Kirimi tidak pernah ditulis plaintext di node - selalu dibaca
// dari tab CONFIG (pola sama dengan "Parse Config FU" di workflow Follow-up).
// ====================================================================
const rows = $input.all().map(i => i.json);

const cfg = {};
for (const r of rows) {
  const k = String(r.key || r.Key || '').trim();
  if (!k) continue;
  const v = (r.value !== undefined && r.value !== null)
    ? r.value
    : ((r.Value !== undefined && r.Value !== null) ? r.Value : '');
  cfg[k] = v;
}

const num = (k, d) => { const n = Number(cfg[k]); return Number.isFinite(n) ? n : d; };
// Sheets kadang mengembalikan nomor telepon sebagai angka ("628228...212.0").
// Buang ekor desimalnya DULU, baru sisakan digit.
const digits = v => String(v === undefined || v === null ? '' : v)
  .trim().replace(/\.0+$/, '').replace(/\D/g, '');
const YES = ['Y', 'YA', 'YES', 'TRUE', '1'];

// Ambang retensi. Default 90 hari = "3 bulan tidak membalas VIRA".
// Ubah lewat CONFIG key `stats_purge_retention_days` tanpa menyentuh kode.
let retentionDays = num('stats_purge_retention_days', 90);
if (retentionDays < 7) retentionDays = 7;      // lantai keras: jangan pernah hapus lead seminggu terakhir
if (retentionDays > 3650) retentionDays = 3650;

// CONFIG `stats_purge_dry_run` = Y  ->  hitung dan laporkan saja, sheet TIDAK disentuh.
// Pakai ini untuk run pertama supaya kelihatan dulu berapa baris yang akan hilang.
const dryRun = YES.indexOf(String(cfg.stats_purge_dry_run || '').trim().toUpperCase()) !== -1;

// Laporan housekeeping ini untuk Steven, bukan untuk admin klien.
const reportPhone = digits(cfg.maintenance_phone) || digits(cfg.admin_phone);

return [{ json: {
  config: {
    kirimi_user_code: String(cfg.kirimi_user_code || '').trim(),
    kirimi_secret: String(cfg.kirimi_secret || '').trim(),
    kirimi_device_id: String(cfg.kirimi_device_id || '').trim(),
    report_phone: reportPhone,
    retention_days: retentionDays,
    dry_run: dryRun,
  },
  now_epoch: Math.floor(Date.now() / 1000),
} }];

// ====================================================================
// PLAN PURGE - retensi STATS 3 bulan (Persada Cisoka Residence)
//
// ATURAN TUNGGAL (keputusan Steven, 2026-08-27):
//   Hapus baris kalau `last_reply_ts` lebih tua dari retention_days (default 90).
//   TIDAK ADA PENGECUALIAN. bot_mode = OFF, survey_status = SCHEDULED,
//   flag_survey = Y, dan nomor admin/tim sendiri SEMUANYA ikut terhapus
//   kalau last_reply_ts-nya sudah lewat ambang.
//
// PERHATIAN 1 - baris dengan last_reply_ts KOSONG atau bukan angka JUGA DIHAPUS.
//   Kosong dibaca sebagai "belum pernah dibalas VIRA sama sekali". Artinya lead
//   hasil impor telemarketer yang belum sempat dibalas akan ikut hilang.
//   Ini pilihan sadar, bukan bug. Kalau berubah pikiran, ubah nilai
//   KEEP_WHEN_EMPTY di bawah jadi true.
//
// PERHATIAN 2 - penghapusan PERMANEN, tidak ada arsip. Baris yang hilang
//   membawa serta lead_source, unit_interest, budget_range, riwayat survey,
//   dan follow_up_count. Backup sheet dulu sebelum run pertama, atau set
//   CONFIG `stats_purge_dry_run` = Y untuk melihat dampaknya lebih dulu.
//
// Nomor baris yang dihapus adalah nomor baris yang BENAR-BENAR dibaca run ini,
// bukan "baris 2..N" - jadi lead yang masuk setelah node Read tidak ikut kena.
// ====================================================================

const KEEP_WHEN_EMPTY = false;   // true = baris tanpa last_reply_ts dibiarkan hidup

const base = $('Parse Config PRG').first().json;
const cfg = base.config;
const now = base.now_epoch;
const cutoff = now - cfg.retention_days * 86400;

const fmtWIB = (epoch) => new Intl.DateTimeFormat('sv-SE', {
  timeZone: 'Asia/Jakarta', year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', hour12: false,
}).format(new Date(epoch * 1000));

const cutoffLabel = fmtWIB(cutoff);
const runAt = fmtWIB(now);

// Periode: workflow jalan tanggal 1 Jan/Apr/Jul/Okt, jadi yang dibersihkan
// adalah kuartal KEMARIN. Dihitung dari H-1 supaya tidak salah lompat.
const pParts = new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Asia/Jakarta', year: 'numeric', month: '2-digit',
}).formatToParts(new Date((now - 86400) * 1000));
const pYear = (pParts.find(x => x.type === 'year') || {}).value;
const pMonth = Number((pParts.find(x => x.type === 'month') || {}).value || 1);
const periode = pYear + '-Q' + Math.ceil(pMonth / 3);

// last_reply_ts ditulis sebagai epoch DETIK (Math.floor(Date.now()/1000)).
// Kalau suatu saat ada nilai milidetik, normalkan dulu supaya tidak dibaca
// sebagai tahun 55.000-an dan luput dari penghapusan.
function replyTs(r) {
  let n = Number(String(r.last_reply_ts === undefined || r.last_reply_ts === null ? '' : r.last_reply_ts).trim());
  if (!Number.isFinite(n) || n <= 0) return 0;
  if (n > 1e12) n = Math.floor(n / 1000);
  return n;
}

const emptyOut = extra => [{ json: Object.assign({
  periode, runAt, cutoffLabel,
  retentionDays: cfg.retention_days, dryRun: cfg.dry_run,
  totalDataRows: 0, purgeCount: 0, keepCount: 0, toDeleteCount: 0,
  blocks: [], blockCount: 0, purgeRows: [],
  reasons: { lewat_ambang: 0, tanpa_timestamp: 0 },
}, extra) }];

const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && typeof r === 'object'
            && r.row_number !== undefined
            && Number(r.row_number) >= 2);

if (!rows.length) {
  console.log('STATS kosong / hanya header - tidak ada yang dihapus.');
  return emptyOut({ report: '[VIRA-PCR] STATS Purge - ' + periode + '\n\nSTATS kosong, tidak ada yang dihapus.' });
}

// Guard skema: pastikan yang terbaca benar-benar tab STATS.
// Ini BUKAN pengecualian baris - ini penjaga supaya workflow tidak menghapus
// isi tab yang salah kalau gid/skema berubah. Lebih baik gagal berisik.
const sample = rows[0];
const REQUIRED = ['No WA', 'last_reply_ts'];
const missing = REQUIRED.filter(c => !(c in sample));
if (missing.length) {
  throw new Error('Kolom wajib tidak ada di sheet yang terbaca: ' + missing.join(', ')
    + '. Tab yang terbaca kemungkinan bukan STATS, atau skemanya berubah. PENGHAPUSAN DIBATALKAN.');
}

const purgeRowNums = [];
const purgeRows = [];
const reasons = { lewat_ambang: 0, tanpa_timestamp: 0 };

for (const r of rows) {
  const ts = replyTs(r);
  let hapus = false;

  if (!ts) {
    // Belum pernah dibalas VIRA sama sekali.
    if (!KEEP_WHEN_EMPTY) { hapus = true; reasons.tanpa_timestamp++; }
  } else if (ts < cutoff) {
    hapus = true; reasons.lewat_ambang++;
  }

  if (!hapus) continue;

  purgeRowNums.push(Number(r.row_number));
  purgeRows.push({
    row: Number(r.row_number),
    no_wa: String(r['No WA'] || '').trim(),
    nama: String(r.Nama || r.nama_lengkap || '').trim(),
    last_reply: ts ? fmtWIB(ts) : '(kosong)',
  });
}

// --- Blok penghapusan ----------------------------------------------
// Nomor baris dikelompokkan jadi blok kontigu lalu diurutkan MENURUN.
// Menghapus dari bawah ke atas membuat nomor baris di atasnya tetap valid
// setelah blok di bawahnya hilang.
purgeRowNums.sort((a, b) => a - b);
const blocks = [];
for (const n of purgeRowNums) {
  const last = blocks[blocks.length - 1];
  if (last && n === last.startRow + last.count) last.count++;
  else blocks.push({ startRow: n, count: 1 });
}
blocks.reverse();

const purgeCount = purgeRowNums.length;
const keepCount = rows.length - purgeCount;
const toDeleteCount = cfg.dry_run ? 0 : purgeCount;

// --- Laporan WA ------------------------------------------------------
const lines = [];
lines.push('[VIRA-PCR] STATS Purge - ' + periode);
if (cfg.dry_run) lines.push('*** DRY RUN - sheet TIDAK disentuh ***');
lines.push('');
lines.push('Ambang    : ' + cfg.retention_days + ' hari tanpa balasan VIRA');
lines.push('Batas     : last_reply_ts sebelum ' + cutoffLabel + ' WIB');
lines.push('Dibaca    : ' + rows.length + ' baris data');
lines.push('');
if (!purgeCount) {
  lines.push('Tidak ada baris yang perlu dihapus.');
} else {
  lines.push((cfg.dry_run ? 'AKAN dihapus : ' : 'Dihapus      : ') + purgeCount + ' baris (' + blocks.length + ' blok)');
  lines.push('Sisa di STATS: ' + keepCount + ' baris');
  lines.push('');
  lines.push('Rincian:');
  lines.push('- last_reply_ts lewat ambang : ' + reasons.lewat_ambang);
  lines.push('- last_reply_ts kosong       : ' + reasons.tanpa_timestamp);
  lines.push('');
  lines.push('Nomor yang hilang:');
  lines.push(purgeRows.slice(0, 20).map(x => '- ' + (x.no_wa || '(tanpa nomor)') + ' | ' + x.last_reply).join('\n')
    + (purgeRows.length > 20 ? '\n- +' + (purgeRows.length - 20) + ' lagi' : ''));
  lines.push('');
  lines.push('Tanpa arsip - baris ini tidak bisa dikembalikan.');
}
const report = lines.join('\n');

console.log('STATS purge ' + periode + ': ' + rows.length + ' baris dibaca | '
  + purgeCount + ' kandidat hapus dalam ' + blocks.length + ' blok | ' + keepCount + ' tetap tinggal'
  + (cfg.dry_run ? ' | DRY RUN, tidak menghapus.' : '.'));
if (purgeCount && purgeCount === rows.length) {
  console.warn('PERHATIAN: SEMUA baris data kena kriteria hapus. Cek dulu apakah kolom last_reply_ts benar terisi sebelum membiarkan ini jalan.');
}
if (blocks.length > 40) {
  console.warn('PERHATIAN: ' + blocks.length + ' blok hapus - mendekati kuota tulis Google Sheets (60/menit). '
    + 'Node Delete sudah retry otomatis, tapi pantau hasilnya.');
}

return [{ json: {
  periode, runAt, cutoffLabel,
  retentionDays: cfg.retention_days,
  dryRun: cfg.dry_run,
  totalDataRows: rows.length,
  purgeCount,
  keepCount,
  toDeleteCount,
  blocks,
  blockCount: blocks.length,
  reasons,
  purgeRows,
  report,
} }];

// Keluarkan satu item per blok. Node Delete jalan sekali per item, jadi urutan
// item = urutan penghapusan - dan blocks sudah diurutkan MENURUN di Plan purge
// supaya penghapusan berjalan dari bawah ke atas.
const plan = $('Plan purge').first().json;
const blocks = plan.blocks || [];

if (!blocks.length) {
  console.log('Tidak ada blok untuk dihapus.');
  return [];
}

console.log('Menghapus ' + blocks.length + ' blok (bawah -> atas): '
  + blocks.map(b => b.startRow + '..' + (b.startRow + b.count - 1)).join(', '));
return blocks.map(b => ({ json: b }));

// Ciutkan lagi jadi 1 item supaya notifikasi WA terkirim sekali, bukan sekali per blok.
const plan = $('Plan purge').first().json;
console.log('STATS bersih: ' + plan.purgeCount + ' baris dihapus permanen, '
  + plan.keepCount + ' baris tetap tinggal.');
return [{ json: plan }];
